        "a11y_message" to e("Message", "Message", "发消息", "메시지", "Сообщение"),
        "a11y_add" to e("Add", "Ajouter", "添加", "추가", "Добавить"),
        "a11y_add_story" to e("Add story", "Ajouter une story", "添加动态", "스토리 추가", "Добавить историю"),
