        "default_audience_sub" to e("Pre-selected when you post a photo or short video. You can still change it each time.", "Présélectionnée quand vous publiez une photo ou une vidéo courte. Vous pouvez la changer à chaque fois.", "发布照片或短视频时默认选中。你仍可每次修改。", "사진이나 짧은 동영상을 올릴 때 미리 선택됩니다. 매번 바꿀 수 있습니다.", "Выбрана заранее при публикации фото или короткого видео. Её можно менять каждый раз."),
        "no_followers_yet" to e("No followers yet.", "Pas encore d'abonnés.", "还没有粉丝。", "아직 팔로워가 없습니다.", "Пока нет подписчиков."),
        "no_following_yet" to e("Not following anyone yet.", "Aucun abonnement pour l'instant.", "还没有关注任何人。", "아직 팔로우하는 사람이 없습니다.", "Пока ни на кого не подписаны."),
        "blocked_users" to e("Blocked users", "Utilisateurs bloqués", "已屏蔽的用户", "차단한 사용자", "Заблокированные пользователи"),
        "blocked_note" to e("People you blocked cannot see your profile or message you. Tap Unblock to undo it.", "Les personnes bloquées ne voient pas votre profil et ne peuvent pas vous écrire. Touchez Débloquer pour annuler.", "被你屏蔽的人无法查看你的资料或给你发消息。点按“取消屏蔽”即可撤销。", "차단한 사람은 내 프로필을 볼 수 없고 메시지도 보낼 수 없어요. 차단 해제를 누르면 되돌릴 수 있어요.", "Заблокированные люди не видят ваш профиль и не могут вам писать. Нажмите «Разблокировать», чтобы отменить."),
        "no_blocked" to e("You have not blocked anyone.", "Vous n'avez bloqué personne.", "你还没有屏蔽任何人。", "차단한 사용자가 없어요.", "Вы никого не блокировали."),
        "saved_posts" to e("Saved posts", "Publications enregistrées", "已保存的帖子", "저장한 게시물", "Сохранённые публикации"),
        "saved_shorts" to e("Saved short videos", "Vidéos courtes enregistrées", "已保存的短视频", "저장한 짧은 동영상", "Сохранённые короткие видео"),
        "no_saved_shorts" to e("No saved short videos yet. Tap the bookmark on a short video to save it here.", "Aucune vidéo courte enregistrée. Touchez le marque-page d'une vidéo courte pour l'enregistrer ici.", "还没有保存的短视频。点击短视频上的书签即可保存到这里。", "저장한 짧은 동영상이 아직 없습니다. 짧은 동영상의 북마크를 눌러 여기에 저장하세요.", "Пока нет сохранённых коротких видео. Нажмите на закладку у видео, чтобы сохранить его здесь."),
        "saved_shorts_note" to e("Videos from accounts you can no longer see are hidden here.", "Les vidéos de comptes que vous ne pouvez plus voir sont masquées ici.", "你无法再查看的账号的视频会在此隐藏。", "더 이상 볼 수 없는 계정의 동영상은 여기에서 숨겨집니다.", "Видео из аккаунтов, которые вы больше не видите, здесь скрыты."),
        "remove_saved" to e("Remove from saved", "Retirer des enregistrés", "取消保存", "저장 취소", "Убрать из сохранённых"),
        "no_saved" to e("No saved posts yet. Tap the bookmark on a post to save it here.", "Aucune publication enregistrée. Touchez le marque-page d'une publication pour l'ajouter ici.", "还没有保存的帖子。点按帖子上的书签即可保存到这里。", "저장한 게시물이 아직 없어요. 게시물의 북마크를 눌러 여기에 저장하세요.", "Пока нет сохранённых публикаций. Нажмите закладку на публикации, чтобы сохранить её здесь."),
        "saved_note" to e("Posts from accounts you can no longer see are hidden here.", "Les publications de comptes que vous ne pouvez plus voir sont masquées ici.", "你无法再查看的账号的帖子不会显示在这里。", "더 이상 볼 수 없는 계정의 게시물은 여기에 표시되지 않아요.", "Публикации аккаунтов, которые вам больше недоступны, здесь скрыты."),
        "load_more" to e("Load more", "Voir plus", "加载更多", "더 보기", "Загрузить ещё"),
        "delete_account" to e("Delete account", "Supprimer le compte", "删除账号", "계정 삭제", "Удалить аккаунт"),
        "delete_account_note" to e("Permanently removes your profile, posts, short videos, stories and chats. This cannot be undone.", "Supprime définitivement votre profil, vos publications, vidéos courtes, stories et discussions. Action irréversible.", "将永久删除你的资料、帖子、短视频、快拍和聊天记录，且无法恢复。", "프로필, 게시물, 숏폼 영상, 스토리, 채팅이 영구적으로 삭제되며 되돌릴 수 없어요.", "Безвозвратно удаляет ваш профиль, публикации, короткие видео, истории и чаты. Отменить это нельзя."),
        "delete_confirm_title" to e("Delete your account?", "Supprimer votre compte ?", "删除你的账号？", "계정을 삭제할까요?", "Удалить аккаунт?"),
        "delete_confirm_body" to e("Everything you shared is removed and your @username becomes free for others. This cannot be undone.", "Tout ce que vous avez partagé est supprimé et votre @nom d'utilisateur redevient disponible. Action irréversible.", "你分享的所有内容都会被删除，你的 @用户名 将可被他人使用。此操作无法撤销。", "공유한 모든 내용이 삭제되고 내 @사용자 이름은 다른 사람이 쓸 수 있게 돼요. 되돌릴 수 없어요.", "Всё, чем вы делились, будет удалено, а ваше @имя станет доступно другим. Отменить это нельзя."),
        "delete_forever" to e("Delete forever", "Supprimer définitivement", "永久删除", "영구 삭제", "Удалить навсегда"),
        "limit_ai_title" to e("Free AI limit reached", "Limite d'IA gratuite atteinte", "已达到免费 AI 额度上限", "무료 AI 한도에 도달했어요", "Бесплатный лимит ИИ исчерпан"),
        "limit_ai_body" to e("Your free AI requests are used up. They reset in about %d h (every 48 hours).", "Vos requêtes d'IA gratuites sont épuisées. Elles se renouvellent dans environ %d h (toutes les 48 heures).", "你的免费 AI 请求已用完，约 %d 小时后重置（每 48 小时一次）。", "무료 AI 요청을 모두 사용했어요. 약 %d시간 후에 초기화돼요(48시간마다).", "Бесплатные запросы к ИИ закончились. Они обновятся примерно через %d ч (каждые 48 часов)."),
        "limit_see_plans" to e("See plans", "Voir les forfaits", "查看套餐", "요금제 보기", "Посмотреть тарифы"),
        "limit_wait" to e("Wait for reset", "Attendre le renouvellement", "等待重置", "초기화 기다리기", "Подождать обновления"),
        "limit_not_now" to e("Not now", "Pas maintenant", "暂不", "나중에", "Не сейчас"),
        "edit_username_hint" to e("Username", "Nom d'utilisateur", "用户名", "사용자 이름", "Имя пользователя"),
        "username_rule" to e("3–20 characters: a–z, 0–9, _ or . — it must be unique. People find you by this name.", "3 à 20 caractères : a–z, 0–9, _ ou . — il doit être unique. On vous trouve avec ce nom.", "3–20 个字符：a–z、0–9、_ 或 .，必须唯一。别人通过此名称找到你。", "3~20자: a–z, 0–9, _ 또는 . — 고유해야 해요. 다른 사람이 이 이름으로 나를 찾아요.", "От 3 до 20 символов: a–z, 0–9, _ или . — имя должно быть уникальным. По нему вас находят."),
        "username_invalid" to e("Username must be 3–20 characters: a–z, 0–9, _ or .", "Le nom d'utilisateur doit contenir 3 à 20 caractères : a–z, 0–9, _ ou .", "用户名须为 3–20 个字符：a–z、0–9、_ 或 .", "사용자 이름은 3~20자(a–z, 0–9, _ 또는 .)여야 해요.", "Имя пользователя: от 3 до 20 символов (a–z, 0–9, _ или .)."),
        "help_legal" to e("Help & legal", "Aide et mentions légales", "帮助与条款", "도움말 및 약관", "Помощь и документы"),
        "help" to e("Help", "Aide", "帮助", "도움말", "Помощь"),
        "help_body" to e("• Who can see your posts? Settings > Privacy & Security.\n• Using too much data? Turn on Data Saver in the Short Video settings.\n• Out of space? Delete old posts or videos, or open Storage & plans.\n• Something broken? Use Report a problem.", "• Qui voit vos publications ? Paramètres > Confidentialité et sécurité.\n• Trop de données ? Activez l'économiseur de données dans les réglages Vidéo courte.\n• Plus d'espace ? Supprimez d'anciennes publications ou vidéos, ou ouvrez Stockage et offres.\n• Un problème ? Utilisez Signaler un problème.", "• 想知道谁能看到你的帖子？设置 > 隐私与安全。\n• 流量用得太多？在短视频设置中开启省流量模式。\n• 空间不足？删除旧帖子或视频，或打开存储与套餐。\n• 遇到故障？请使用“报告问题”。", "• 내 게시물을 누가 볼 수 있는지 궁금하다면 설정 > 개인정보 및 보안을 확인하세요.\n• 데이터가 많이 쓰이나요? 숏 비디오 설정에서 데이터 절약을 켜세요.\n• 공간이 부족한가요? 오래된 게시물이나 영상을 삭제하거나 저장 공간 및 요금제를 열어 보세요.\n• 문제가 있나요? 문제 신고를 이용하세요.", "• Кто видит ваши публикации? Настройки > Конфиденциальность и безопасность.\n• Много трафика? Включите экономию данных в настройках коротких видео.\n• Не хватает места? Удалите старые публикации или видео либо откройте «Хранилище и тарифы».\n• Что-то не работает? Воспользуйтесь «Сообщить о проблеме»."),
        "terms" to e("Terms of Service", "Conditions d'utilisation", "服务条款", "이용약관", "Условия использования"),
        "privacy_policy" to e("Privacy Policy", "Politique de confidentialité", "隐私政策", "개인정보 처리방침", "Политика конфиденциальности"),
        "legal_draft_note" to e("Plain-language draft, shown in English only. The final legal text must be checked for your launch countries before release.", "Brouillon en langage simple, affiché en anglais uniquement. Le texte juridique final doit être vérifié pour vos pays de lancement avant la sortie.", "这是通俗易懂的草稿，仅以英文显示。正式发布前，必须针对上线国家核对最终法律文本。", "쉬운 말로 쓴 초안이며 영어로만 표시됩니다. 출시 전에 출시 국가에 맞춰 최종 법률 문서를 검토해야 합니다.", "Черновик простым языком, показан только на английском. Перед выпуском окончательный юридический текст нужно проверить для стран запуска."),
        "terms_body" to e("These are plain-language terms for the test version of Sociax.\n\n1. You must be 15 or older to use Sociax.\n2. You are responsible for what you post, send and say. Do not post content that harms, harasses or threatens others, or that breaks the law.\n3. You can block people and report posts, short videos and problems. Reports are saved for review.\n4. Sociax AI can be wrong. Check important answers yourself.\n5. There is one paid plan, Sociax Pro (US $15 for 30 days). In this version it is a one-time payment that does not renew automatically. Free daily media allowance: 500 MB; Pro: 1.5 GB per day. Prices and allowances can change before release.\n6. You can delete your account at any time in Settings > Account. This cannot be undone.", "", "", "", ""),
        "privacy_policy_body" to e("What Sociax keeps (plain-language draft):\n\n• Your Google sign-in id, display name, @username, age, bio and profile photo.\n• Your posts, short videos, stories, comments, likes, follows, blocks, messages and notifications.\n• Your media and AI usage totals, so the free allowances and paid plans can be enforced.\n• The reports and problem reports you send.\n\nAI: when you ask Sociax AI something, only that request is sent to the AI providers (Grok and Gemini). AI does not read your private one-to-one chats. In a group, AI sees only the message that contains @AI, and only if an admin turned AI on.\n\nDevice: Sociax does not ask for your location, microphone or contacts. A photo or video is shared only when you choose it from your gallery or camera app.\n\nSecurity: API keys stay on the server, never in the app.\n\nDeleting your account removes your profile, posts, short videos, stories and chats from Sociax. Uploaded files are removed from Cloudinary in the background.", "", "", "", ""),
        "report_problem" to e("Report a problem", "Signaler un problème", "报告问题", "문제 신고", "Сообщить о проблеме"),
        "report_problem_hint" to e("Describe what went wrong (at least 10 characters).", "Décrivez ce qui n'a pas fonctionné (au moins 10 caractères).", "请描述出了什么问题（至少 10 个字符）。", "무엇이 잘못되었는지 적어 주세요(10자 이상).", "Опишите, что пошло не так (не менее 10 символов)."),
        "report_problem_send" to e("Send", "Envoyer", "发送", "보내기", "Отправить"),
        "report_problem_sent" to e("Thank you. Your report was sent.", "Merci. Votre signalement a été envoyé.", "谢谢，你的反馈已发送。", "감사합니다. 신고가 전송되었어요.", "Спасибо. Ваше сообщение отправлено."),
        "close" to e("Close", "Fermer", "关闭", "닫기", "Закрыть"),
        "google_account" to e("Google account", "Compte Google", "Google 账号", "Google 계정", "Аккаунт Google"),
        "pro_title" to e("Sociax Pro — \$15 / month", "Sociax Pro — 15 \$ / mois", "Sociax Pro — 每月 \$15", "Sociax Pro — 월 \$15", "Sociax Pro — \$15 в месяц"),
        "pro_body" to e("One plan, everything included:\n• Media: 1.5 GB per day (free: 500 MB)\n• AI: 7× the free AI allowance\n• AI creation limits: up to 3 videos and 4 images per day (once AI creation is available)\n• No ads", "Une seule offre, tout inclus :\n• Médias : 1,5 Go par jour (gratuit : 500 Mo)\n• IA : 7× le quota IA gratuit\n• Création IA : jusqu'à 3 vidéos et 4 images par jour (dès que la création IA est disponible)\n• Sans publicité", "一个套餐，全部包含：\n• 媒体：每天 1.5 GB（免费版 500 MB）\n• AI：免费 AI 额度的 7 倍\n• AI 创作：每天最多 3 个视频和 4 张图片（AI 创作上线后）\n• 无广告", "하나의 요금제로 모두 이용:\n• 미디어: 하루 1.5GB (무료 500MB)\n• AI: 무료 AI 사용량의 7배\n• AI 만들기: 하루 최대 동영상 3개, 이미지 4장 (AI 만들기 제공 시)\n• 광고 없음", "Один тариф — всё включено:\n• Медиа: 1,5 ГБ в день (бесплатно: 500 МБ)\n• ИИ: в 7 раз больше бесплатного лимита\n• Создание ИИ: до 3 видео и 4 изображений в день (когда создание ИИ станет доступно)\n• Без рекламы"),
        "pro_terms" to e("One-time payment for 30 days of Sociax Pro. It does not renew automatically, so there is nothing to cancel: pay again to continue. Benefits start right after the server verifies your payment. When it ends, your content stays and you go back to the free limits.", "Paiement unique pour 30 jours de Sociax Pro. Pas de renouvellement automatique, donc rien à résilier : payez à nouveau pour continuer. Les avantages commencent dès que le serveur vérifie votre paiement. À la fin, votre contenu reste et vous revenez aux limites gratuites.", "一次性付款，获得 30 天 Sociax Pro。不会自动续费，因此无需取消：到期后需再次付款。服务器验证付款后权益立即生效。到期后你的内容会保留，额度恢复为免费版。", "30일 Sociax Pro를 위한 일회성 결제예요. 자동 갱신되지 않아 해지할 것이 없어요. 계속하려면 다시 결제하세요. 서버가 결제를 확인하면 혜택이 바로 시작돼요. 끝나도 콘텐츠는 그대로 남고 무료 한도로 돌아가요.", "Разовый платёж за 30 дней Sociax Pro. Автопродления нет, отменять нечего: чтобы продолжить, оплатите снова. Преимущества включаются сразу после проверки платежа сервером. По окончании ваш контент сохраняется, а лимиты возвращаются к бесплатным."),
        "pro_buy" to e("Buy Sociax Pro — \$15 / 1 month", "Acheter Sociax Pro — 15 \$ / 1 mois", "购买 Sociax Pro — 15 美元 / 1 个月", "Sociax Pro 구매 — \$15 / 1개월", "Купить Sociax Pro — 15 \$ / 1 месяц"),
        "pro_buy_more" to e("Add 1 more month — \$15", "Ajouter 1 mois — 15 \$", "再加 1 个月 — 15 美元", "1개월 추가 — \$15", "Добавить 1 месяц — 15 \$"),
        "pro_active" to e("Sociax Pro is active until %s.", "Sociax Pro est actif jusqu'au %s.", "Sociax Pro 有效期至 %s。", "Sociax Pro는 %s까지 사용할 수 있어요.", "Sociax Pro активен до %s."),
        "pay_success" to e("Payment confirmed. Sociax Pro is active.", "Paiement confirmé. Sociax Pro est actif.", "付款已确认，Sociax Pro 已开通。", "결제가 확인되었어요. Sociax Pro가 활성화되었어요.", "Платёж подтверждён. Sociax Pro активен."),
        "plan_free_note" to e("The free plan stays free: 500 MB of media per day. Paying is optional and only raises the limits. There is one paid plan: Sociax Pro.", "L'offre gratuite reste gratuite : 500 Mo de médias par jour. Payer est facultatif et ne fait qu'augmenter les limites. Il n'y a qu'une seule offre payante : Sociax Pro.", "免费版始终免费：每天 500 MB 媒体额度。付费是可选的，只会提高额度。只有一个付费套餐：Sociax Pro。", "무료 요금제는 계속 무료예요: 하루 미디어 500MB. 결제는 선택이며 한도만 늘려 줘요. 유료 요금제는 Sociax Pro 하나뿐이에요.", "Бесплатный тариф остаётся бесплатным: 500 МБ медиа в день. Оплата необязательна и только повышает лимиты. Платный тариф один: Sociax Pro."),
        "storage_line" to e("Media today: %s MB of %d MB used (posts, photos, videos and files combined)", "Médias aujourd'hui : %s Mo sur %d Mo utilisés (publications, photos, vidéos et fichiers ensemble)", "今日媒体：已用 %s MB / %d MB（帖子、照片、视频和文件合计）", "오늘 미디어: %2\$d MB 중 %1\$s MB 사용 (게시물, 사진, 영상, 파일 합계)", "Медиа сегодня: использовано %s МБ из %d МБ (публикации, фото, видео и файлы вместе)"),
        "storage_left" to e("%s MB left today", "%s Mo restants aujourd'hui", "今日剩余 %s MB", "오늘 %s MB 남음", "Осталось сегодня %s МБ"),
        "storage_reset" to e("The counter resets at %s (24 hours after your first upload of the day). Your posts are never deleted by the reset.", "Le compteur est remis à zéro à %s (24 heures après votre premier envoi du jour). Vos publications ne sont jamais supprimées par la remise à zéro.", "计数将在 %s 重置（当天首次上传后的 24 小时）。重置不会删除你的帖子。", "%s에 초기화돼요(오늘 첫 업로드 후 24시간). 초기화로 게시물이 삭제되지는 않아요.", "Счётчик обнулится в %s (через 24 часа после первой загрузки за день). Обнуление никогда не удаляет ваши публикации."),
        "storage_reset_none" to e("Your 24-hour counter starts with your next upload.", "Votre compteur de 24 heures démarre à votre prochain envoi.", "你的 24 小时计数将从下一次上传开始。", "24시간 카운터는 다음 업로드부터 시작돼요.", "24-часовой счётчик начнётся со следующей загрузки."),
        "limit_ai_offer" to e("You can wait for the reset, or upgrade to Sociax Pro (\$15 per month, 7× the free AI allowance).", "Vous pouvez attendre le renouvellement ou passer à Sociax Pro (15 \$ par mois, 7× le quota IA gratuit).", "你可以等待重置，或升级到 Sociax Pro（每月 15 美元，免费 AI 额度的 7 倍）。", "초기화를 기다리거나 Sociax Pro(월 \$15, 무료 AI 한도의 7배)로 업그레이드할 수 있어요.", "Можно дождаться обновления или перейти на Sociax Pro (15 \$ в месяц, в 7 раз больше бесплатного лимита ИИ)."),
        "limit_media_title" to e("Daily media limit reached", "Limite quotidienne de médias atteinte", "已达到每日媒体额度上限", "오늘의 미디어 한도에 도달했어요", "Дневной лимит медиа исчерпан"),
        "limit_media_body" to e("You have used today's media allowance of your plan, so this upload was not made. It resets in about %d h. Your existing posts are not deleted.", "Vous avez utilisé le quota de médias du jour de votre offre ; cet envoi n'a donc pas été effectué. Il se renouvelle dans environ %d h. Vos publications existantes ne sont pas supprimées.", "你已用完当前套餐今天的媒体额度，因此本次上传未完成。约 %d 小时后重置。已有的帖子不会被删除。", "현재 요금제의 오늘 미디어 한도를 모두 사용해서 이번 업로드는 완료되지 않았어요. 약 %d시간 후에 초기화돼요. 기존 게시물은 삭제되지 않아요.", "Вы использовали дневной лимит медиа по вашему тарифу, поэтому загрузка не выполнена. Он обновится примерно через %d ч. Ваши публикации не удаляются."),
        "limit_media_offer" to e("You can wait for the reset, or upgrade to Sociax Pro (\$15 per month, 1.5 GB per day instead of 500 MB).", "Vous pouvez attendre le renouvellement ou passer à Sociax Pro (15 \$ par mois, 1,5 Go par jour au lieu de 500 Mo).", "你可以等待重置，或升级到 Sociax Pro（每月 15 美元，每天 1.5 GB，免费版为 500 MB）。", "초기화를 기다리거나 Sociax Pro(월 \$15, 하루 500MB 대신 1.5GB)로 업그레이드할 수 있어요.", "Можно дождаться обновления или перейти на Sociax Pro (15 \$ в месяц, 1,5 ГБ в день вместо 500 МБ)."),
        "videos_note" to e("Videos come in Short Video.", "Les vidéos se publient dans Vidéos courtes.", "视频请在“短视频”中发布。", "영상은 숏폼에서 올려요.", "Видео публикуются в «Коротких видео»."),
        "no_shorts" to e("No short videos yet. Tap + to share the first one.", "Aucune vidéo courte pour l'instant. Touchez + pour partager la première.", "还没有短视频。点击 + 发布第一条。", "아직 숏폼이 없어요. +를 눌러 첫 영상을 올려보세요.", "Коротких видео пока нет. Нажмите +, чтобы опубликовать первое."),
        "lock_setup_title" to e("Protect your account", "Protégez votre compte", "保护你的账号", "계정을 보호하세요", "Защитите свой аккаунт"),
        "lock_setup_sub_must" to e("Choose a 4-digit PIN or a pattern. You need it to open Sociax. This step cannot be skipped.", "Choisissez un code PIN à 4 chiffres ou un schéma. Il sera demandé pour ouvrir Sociax. Cette étape est obligatoire.", "请选择 4 位 PIN 码或图案。打开 Sociax 时需要它。此步骤不能跳过。", "4자리 PIN 또는 패턴을 선택하세요. Sociax를 열 때 필요해요. 이 단계는 건너뛸 수 없어요.", "Выберите 4-значный PIN-код или графический ключ. Он нужен для входа в Sociax. Этот шаг нельзя пропустить."),
        "lock_setup_sub" to e("Choose a new 4-digit PIN or pattern.", "Choisissez un nouveau code PIN à 4 chiffres ou un nouveau schéma.", "请选择新的 4 位 PIN 码或图案。", "새 4자리 PIN 또는 패턴을 선택하세요.", "Выберите новый 4-значный PIN-код или графический ключ."),
        "lock_type_pin" to e("4-digit PIN", "Code PIN à 4 chiffres", "4 位 PIN 码", "4자리 PIN", "4-значный PIN-код"),
        "lock_type_pattern" to e("Pattern", "Schéma", "图案", "패턴", "Графический ключ"),
        "lock_enter_new_pin" to e("Enter a new 4-digit PIN", "Entrez un nouveau code PIN à 4 chiffres", "输入新的 4 位 PIN 码", "새 4자리 PIN을 입력하세요", "Введите новый 4-значный PIN-код"),
        "lock_confirm_pin" to e("Enter the PIN again to confirm", "Entrez à nouveau le PIN pour confirmer", "请再次输入 PIN 码以确认", "확인을 위해 PIN을 다시 입력하세요", "Введите PIN-код ещё раз для подтверждения"),
        "lock_draw_pattern" to e("Draw a pattern (connect at least 4 dots)", "Dessinez un schéma (reliez au moins 4 points)", "绘制图案（至少连接 4 个点）", "패턴을 그리세요 (점 4개 이상 연결)", "Нарисуйте ключ (соедините не менее 4 точек)"),
        "lock_confirm_pattern" to e("Draw the pattern again to confirm", "Dessinez à nouveau le schéma pour confirmer", "请再次绘制图案以确认", "확인을 위해 패턴을 다시 그리세요", "Нарисуйте ключ ещё раз для подтверждения"),
        "lock_mismatch" to e("They do not match. Start again.", "Ils ne correspondent pas. Recommencez.", "两次输入不一致，请重新开始。", "일치하지 않아요. 처음부터 다시 하세요.", "Не совпадает. Начните заново."),
        "lock_pattern_short" to e("Connect at least 4 dots.", "Reliez au moins 4 points.", "请至少连接 4 个点。", "점을 4개 이상 연결하세요.", "Соедините не менее 4 точек."),
        "lock_enter_pin" to e("Enter your PIN", "Entrez votre code PIN", "输入你的 PIN 码", "PIN을 입력하세요", "Введите PIN-код"),
        "lock_draw_to_unlock" to e("Draw your pattern", "Dessinez votre schéma", "绘制你的图案", "패턴을 그리세요", "Нарисуйте ваш ключ"),
        "lock_wrong" to e("Wrong PIN or pattern. %d tries left before a short wait.", "PIN ou schéma incorrect. Encore %d essais avant une courte attente.", "PIN 码或图案错误。还有 %d 次尝试，之后需要稍等。", "PIN 또는 패턴이 틀렸어요. 잠시 기다리기 전까지 %d번 남았어요.", "Неверный PIN-код или ключ. Осталось попыток до паузы: %d."),
        "lock_wait" to e("Too many wrong tries. Try again in %d s.", "Trop d'essais incorrects. Réessayez dans %d s.", "错误次数过多，请 %d 秒后再试。", "틀린 횟수가 너무 많아요. %d초 후에 다시 시도하세요.", "Слишком много неверных попыток. Повторите через %d с."),
        "lock_forgot" to e("Forgot PIN/Pattern?", "PIN/schéma oublié ?", "忘记 PIN 码/图案？", "PIN/패턴을 잊으셨나요?", "Забыли PIN-код/ключ?"),
        "lock_recover_title" to e("Verify it's you", "Vérifiez votre identité", "验证是你本人", "본인 확인", "Подтвердите, что это вы"),
        "lock_recover_body" to e("Sign in again with the Google account of this Sociax account. Your old PIN or pattern cannot be shown or emailed; you will choose a new one.", "Reconnectez-vous avec le compte Google de ce compte Sociax. Votre ancien PIN ou schéma ne peut être ni affiché ni envoyé par e-mail ; vous en choisirez un nouveau.", "请使用此 Sociax 账号对应的 Google 账号重新登录。旧的 PIN 码或图案无法显示或通过邮件发送，你需要设置新的。", "이 Sociax 계정의 Google 계정으로 다시 로그인하세요. 이전 PIN이나 패턴은 보여 주거나 이메일로 보낼 수 없어요. 새로 정하게 돼요.", "Войдите снова через Google-аккаунт этого аккаунта Sociax. Старый PIN-код или ключ нельзя показать или отправить по почте — вы задаёте новый."),
        "lock_recover_btn" to e("Verify with Google", "Vérifier avec Google", "使用 Google 验证", "Google로 확인", "Подтвердить через Google"),
        "lock_recover_failed" to e("Could not verify. Use the Google account you signed up with, then try again.", "Vérification impossible. Utilisez le compte Google avec lequel vous vous êtes inscrit, puis réessayez.", "验证失败。请使用注册时的 Google 账号，然后重试。", "확인할 수 없어요. 가입할 때 쓴 Google 계정을 사용한 뒤 다시 시도하세요.", "Не удалось подтвердить. Используйте Google-аккаунт, с которым вы регистрировались, и повторите."),
        "lock_recover_support" to e("Cannot use that Google account? Contact Sociax support: they verify who you are before helping, and never bypass the lock without that. (The support contact will be shown here before release.)", "Vous ne pouvez pas utiliser ce compte Google ? Contactez le support Sociax : il vérifie votre identité avant d'aider et ne contourne jamais le verrou sans cela. (Le contact du support sera affiché ici avant la sortie.)", "无法使用该 Google 账号？请联系 Sociax 客服：他们会先验证你的身份，绝不会在未验证的情况下绕过锁。（客服联系方式将在正式发布前显示在此处。）", "그 Google 계정을 쓸 수 없나요? Sociax 지원팀에 문의하세요. 본인 확인 없이는 잠금을 우회해 주지 않아요. (지원 연락처는 출시 전에 여기에 표시돼요.)", "Не можете использовать этот Google-аккаунт? Обратитесь в поддержку Sociax: она проверит вашу личность и не обойдёт блокировку без этого. (Контакт поддержки появится здесь до релиза.)"),
        "lock_settings_title" to e("App Lock", "Verrouillage de l'app", "应用锁", "앱 잠금", "Блокировка приложения"),
        "lock_current_type" to e("Current lock: %s", "Verrou actuel : %s", "当前锁定方式：%s", "현재 잠금: %s", "Текущая блокировка: %s"),
        "lock_change" to e("Change PIN / pattern", "Changer le PIN / schéma", "更改 PIN 码/图案", "PIN/패턴 변경", "Изменить PIN-код / ключ"),
        "lock_verify_current" to e("Enter your current PIN or pattern to continue.", "Entrez votre PIN ou schéma actuel pour continuer.", "请输入当前的 PIN 码或图案以继续。", "계속하려면 현재 PIN 또는 패턴을 입력하세요.", "Введите текущий PIN-код или ключ, чтобы продолжить."),
        "lock_timeout" to e("Ask again after", "Redemander après", "多久后再次要求", "다시 요구하는 시간", "Спрашивать снова через"),
        "lock_t_30s" to e("30 seconds", "30 secondes", "30 秒", "30초", "30 секунд"),
        "lock_t_1m" to e("1 minute", "1 minute", "1 分钟", "1분", "1 минуту"),
        "lock_t_5m" to e("5 minutes", "5 minutes", "5 分钟", "5분", "5 минут"),
        "lock_t_15m" to e("15 minutes", "15 minutes", "15 分钟", "15분", "15 минут"),
        "lock_timeout_note" to e("Sociax asks for your PIN or pattern when you come back after this time, and always after it was closed.", "Sociax demande votre PIN ou schéma quand vous revenez après ce délai, et toujours après une fermeture complète.", "超过此时间后返回应用，或应用被完全关闭后重新打开时，Sociax 会要求输入 PIN 码或图案。", "이 시간이 지난 뒤 돌아오거나 앱을 완전히 닫았다가 열면 Sociax가 PIN 또는 패턴을 물어봐요.", "Sociax запрашивает PIN-код или ключ, если вы вернулись позже этого времени, и всегда после полного закрытия."),
        "alarm_prompt" to e("Would you like Sociax to play an alarm every day at 3:00 AM and 3:00 PM?", "Voulez-vous que Sociax sonne une alarme tous les jours à 3h00 et à 15h00 ?", "你希望 Sociax 每天在凌晨 3:00 和下午 3:00 响铃提醒吗？", "Sociax가 매일 오전 3:00와 오후 3:00에 알람을 울리게 할까요?", "Хотите, чтобы Sociax каждый день в 3:00 и в 15:00 включал будильник?"),
        "alarm_perm_needed" to e("Alarms need the Notifications permission, so they stay Off for now. You can turn them on any time in Settings > Daily Alarms.", "Les alarmes nécessitent l'autorisation Notifications ; elles restent donc désactivées pour l'instant. Vous pouvez les activer à tout moment dans Réglages > Alarmes quotidiennes.", "闹钟需要“通知”权限，因此目前保持关闭。你可以随时在 设置 > 每日闹钟 中开启。", "알람에는 알림 권한이 필요해서 지금은 꺼져 있어요. 설정 > 매일 알람에서 언제든 켤 수 있어요.", "Для будильников нужно разрешение на уведомления, поэтому пока они выключены. Включить их можно в любой момент: Настройки > Ежедневные будильники."),
        "alarm_settings_title" to e("Daily Alarms", "Alarmes quotidiennes", "每日闹钟", "매일 알람", "Ежедневные будильники"),
        "alarm_master" to e("Daily alarms", "Alarmes quotidiennes", "每日闹钟", "매일 알람", "Ежедневные будильники"),
        "alarm_state_on" to e("On — rings without internet", "Activées — sonnent sans internet", "已开启 — 无需网络即可响铃", "켜짐 — 인터넷 없이 울려요", "Включены — работают без интернета"),
        "alarm_state_off" to e("Off", "Désactivées", "已关闭", "꺼짐", "Выключены"),
        "alarm_times" to e("Alarm times: 3:00 AM and 3:00 PM, by your phone's local time and time zone (fixed in this version).", "Heures : 3h00 et 15h00, selon l'heure locale et le fuseau horaire de votre téléphone (fixes dans cette version).", "闹钟时间：凌晨 3:00 和下午 3:00，按手机当前本地时间和时区（此版本固定）。", "알람 시간: 오전 3:00와 오후 3:00, 휴대폰의 현지 시간과 시간대 기준(이 버전에서는 고정).", "Время: 3:00 и 15:00 по местному времени и часовому поясу телефона (в этой версии фиксировано)."),
        "alarm_next" to e("Next alarm: %s", "Prochaine alarme : %s", "下一次闹钟：%s", "다음 알람: %s", "Следующий будильник: %s"),
        "alarm_sound" to e("Alarm sound", "Sonnerie", "闹钟铃声", "알람 소리", "Мелодия будильника"),
        "alarm_s1" to e("Sunrise", "Lever du soleil", "日出", "일출", "Рассвет"),
        "alarm_s2" to e("Bell", "Cloche", "铃声", "종소리", "Колокол"),
        "alarm_s3" to e("Beep", "Bip", "嘀嘀声", "삐삐", "Сигнал"),
        "alarm_s4" to e("Chime", "Carillon", "钟琴", "차임", "Перезвон"),
        "alarm_s5" to e("Pulse", "Pulsation", "脉冲", "펄스", "Пульс"),
        "alarm_stop_preview" to e("Stop", "Arrêter", "停止", "정지", "Стоп"),
        "alarm_perm_status" to e("Notifications permission: %s", "Autorisation Notifications : %s", "通知权限：%s", "알림 권한: %s", "Разрешение на уведомления: %s"),
        "alarm_perm_allowed" to e("Allowed", "Accordée", "已允许", "허용됨", "Разрешено"),
        "alarm_perm_denied" to e("Not allowed", "Refusée", "未允许", "허용 안 됨", "Не разрешено"),
        "alarm_open_settings" to e("Open notification settings", "Ouvrir les réglages des notifications", "打开通知设置", "알림 설정 열기", "Открыть настройки уведомлений"),
        "alarm_honest" to e("The alarm uses your phone's alarm scheduler and sounds stored in the app, so it can ring with no internet. It is not guaranteed: battery saver, restricted battery mode, Do Not Disturb, a muted alarm volume or other phone settings can stop it.", "L'alarme utilise le planificateur d'alarmes du téléphone et des sons intégrés à l'app : elle peut sonner sans internet. Ce n'est pas garanti : économie de batterie, mode batterie restreint, Ne pas déranger, volume d'alarme coupé ou d'autres réglages peuvent l'empêcher.", "闹钟使用手机的闹钟调度和应用内置铃声，因此无需网络也能响铃。但无法保证：省电模式、受限电池模式、勿扰模式、闹钟音量静音或其他手机设置都可能使其不响。", "알람은 휴대폰의 알람 스케줄러와 앱에 내장된 소리를 사용하므로 인터넷 없이도 울려요. 보장되지는 않아요. 절전 모드, 배터리 제한, 방해 금지 모드, 알람 음량 음소거 등 휴대폰 설정이 알람을 막을 수 있어요.", "Будильник использует планировщик телефона и звуки, встроенные в приложение, поэтому звонит без интернета. Гарантии нет: режим экономии заряда, ограничение батареи, «Не беспокоить», отключённая громкость будильника и другие настройки могут его заглушить."),
        "alarm_notif_title" to e("Sociax daily alarm", "Alarme quotidienne Sociax", "Sociax 每日闹钟", "Sociax 매일 알람", "Ежедневный будильник Sociax"),
        "alarm_notif_text" to e("Your daily alarm is ringing.", "Votre alarme quotidienne sonne.", "你的每日闹钟正在响铃。", "매일 알람이 울리고 있어요.", "Ваш ежедневный будильник звонит."),
        "alarm_notif_stop" to e("Stop", "Arrêter", "停止", "정지", "Стоп"),
